export const productMap: Record<string, Product> = products.reduce(
  (acc, product) => {
    acc[product.slug] = product;
    return acc;
  },
  {} as Record<string, Product>,
);

export function getProductBySlug(slug: string): Product | undefined {
  return productMap[slug];
}

export function getProductById(id: string): Product | undefined {
  return products.find((product) => product.id === id);
}

export const featuredProducts = products.filter((product) => product.featured);
export const popularProducts = products.filter((product) => product.popular);

export function getProductsByCategory(category: CategoryId): Product[] {
  return products.filter((product) => product.category === category);
}

export function getRelatedProducts(product: Product, limit = 3): Product[] {
  const sameCategory = products.filter(
    (candidate) =>
      candidate.id !== product.id && candidate.category === product.category,
  );
  const rest = products.filter(
    (candidate) =>
      candidate.id !== product.id && candidate.category !== product.category,
  );
  return [...sameCategory, ...rest].slice(0, limit);
}

/** True only once at least one product has a confirmed price. */
export const hasPublishedPrices = products.some(
  (product) => !product.quoteRequired && product.price !== null,
);
