"use client";

import Link from "next/link";
import { Minus, Pencil, Plus, Trash2 } from "lucide-react";
import type { CartItem } from "@/lib/types";
import { ProductVisual } from "@/components/product/ProductVisual";
import { PlatformIcon } from "@/components/product/PlatformIcons";
import { useCart } from "@/lib/cart-context";
import { getCategoryTitle } from "@/config/categories";
import { cn, formatPrice, getPlatformLabel } from "@/lib/utils";

export function CartLineItem({
  item,
  compact = false,
  onNavigate,
}: {
  item: CartItem;
  compact?: boolean;
  onNavigate?: () => void;
}) {
  const { currency, setQuantity, removeItem } = useCart();
  const isCustom = Boolean(item.custom);
  const editHref = isCustom ? "/custom-order" : `/products/${item.slug}`;

  return (
    <li
      className={cn(
        "relative flex gap-3.5 rounded-xl border border-white/8 bg-white/[0.02] p-3",
        compact ? "sm:gap-4" : "sm:gap-5 sm:p-4",
      )}
    >
      <Link
        href={editHref}
        onClick={onNavigate}
        className={cn(
          "relative shrink-0 overflow-hidden rounded-lg border border-white/8",
          compact ? "h-16 w-16" : "h-20 w-20 sm:h-24 sm:w-28",
        )}
        aria-label={`View ${item.title}`}
      >
        <ProductVisual
          visual={item.visual}
          label=""
          className="h-full w-full"
        />
      </Link>

      <div className="min-w-0 flex-1">
        <div className="flex items-start justify-between gap-3">
          <div className="min-w-0">
            <p className="text-[11px] uppercase tracking-[0.16em] text-silver-500">
              {getCategoryTitle(item.category)}
            </p>
            <Link
              href={editHref}
              onClick={onNavigate}
              className="mt-0.5 block truncate text-[14.5px] font-semibold text-white hover:text-violet-200"
            >
              {item.title}
            </Link>
          </div>
          <p className="shrink-0 text-right text-[13px] font-semibold text-gold-200">
            {formatPrice(item.price, currency, item.quoteRequired)}
          </p>
        </div>

        <div className="mt-2 flex flex-wrap items-center gap-1.5">
          <span className="inline-flex items-center gap-1.5 rounded-md border border-white/10 bg-white/[0.04] px-2 py-0.5 text-[11px] text-silver-300">
            <PlatformIcon platform={item.platform} />
            {getPlatformLabel(item.platform)}
          </span>
          {item.options.map((option) => (
            <span
              key={option.groupId}
              className="rounded-md border border-white/8 bg-white/[0.03] px-2 py-0.5 text-[11px] text-silver-400"
            >
              <span className="text-silver-500">{option.groupLabel}: </span>
              {option.choiceLabels.join(", ")}
            </span>
          ))}
        </div>

        {item.custom ? (
          <div className="mt-2 rounded-lg border border-violet-300/15 bg-violet-500/[0.06] p-2.5">
            <p className="text-[11px] font-medium uppercase tracking-[0.14em] text-violet-200">
              Custom request
            </p>
            <ul className="mt-1.5 flex flex-col gap-1">
              {item.custom.values.map((value) => (
                <li key={value.serviceId} className="text-[12px] text-silver-300">
                  <span className="text-silver-500">{value.serviceId}: </span>
                  {value.current ? `${value.current} → ` : ""}
                  {value.desired || "target confirmed in ticket"}
                </li>
              ))}
            </ul>
            {item.custom.instructions ? (
              <p className="mt-1.5 line-clamp-2 text-[12px] italic text-silver-400">
                “{item.custom.instructions}”
              </p>
            ) : null}
          </div>
        ) : null}

        <div className="mt-3 flex flex-wrap items-center justify-between gap-3">
          <div className="inline-flex items-center rounded-lg border border-white/10 bg-white/[0.03]">
            <button
              type="button"
              onClick={() => setQuantity(item.key, item.quantity - 1)}
              disabled={item.quantity <= 1}
              aria-label={`Decrease quantity of ${item.title}`}
              className="grid h-8 w-8 place-items-center rounded-l-lg text-silver-300 transition hover:bg-white/[0.07] hover:text-white disabled:opacity-35"
            >
              <Minus className="h-3.5 w-3.5" aria-hidden="true" />
            </button>
            <span
              className="min-w-8 text-center text-[13px] font-medium text-white"
              aria-live="polite"
            >
              {item.quantity}
            </span>
            <button
              type="button"
              onClick={() => setQuantity(item.key, item.quantity + 1)}
              disabled={item.quantity >= 99}
              aria-label={`Increase quantity of ${item.title}`}
              className="grid h-8 w-8 place-items-center rounded-r-lg text-silver-300 transition hover:bg-white/[0.07] hover:text-white disabled:opacity-35"
            >
              <Plus className="h-3.5 w-3.5" aria-hidden="true" />
            </button>
          </div>

          <div className="flex items-center gap-1">
            <Link
              href={editHref}
              onClick={onNavigate}
              className="inline-flex items-center gap-1.5 rounded-lg px-2.5 py-1.5 text-[12.5px] text-silver-300 transition hover:bg-white/[0.06] hover:text-white"
            >
              <Pencil className="h-3.5 w-3.5" aria-hidden="true" />
              Edit
            </Link>
            <button
              type="button"
              onClick={() => removeItem(item.key)}
              className="inline-flex items-center gap-1.5 rounded-lg px-2.5 py-1.5 text-[12.5px] text-silver-400 transition hover:bg-red-500/10 hover:text-red-200"
            >
              <Trash2 className="h-3.5 w-3.5" aria-hidden="true" />
              <span>Remove</span>
              <span className="sr-only"> {item.title} from cart</span>
            </button>
          </div>
        </div>
      </div>
    </li>
  );
}
