"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import {
  ArrowUpRight,
  ChevronRight,
  MessageSquareText,
  Search,
  ShoppingCart,
} from "lucide-react";
import { Dialog } from "@/components/ui/Dialog";
import { ButtonLink } from "@/components/ui/Button";
import { Logo } from "@/components/brand/Logo";
import { categories } from "@/config/categories";
import { footerLinks, navLinks, siteConfig } from "@/config/site";
import { useCart } from "@/lib/cart-context";
import { useUI } from "@/lib/ui-context";
import { discordHref } from "@/lib/links";
import { cn } from "@/lib/utils";

export function MobileMenu({
  open,
  onClose,
}: {
  open: boolean;
  onClose: () => void;
}) {
  const pathname = usePathname();
  const { count, hydrated, openDrawer } = useCart();
  const { openSearch } = useUI();

  const isActive = (href: string) =>
    href === "/" ? pathname === "/" : pathname.startsWith(href);

  return (
    <Dialog
      open={open}
      onClose={onClose}
      title="Menu"
      variant="sheet-right"
      hideHeader
      className="max-w-[21rem]"
    >
      <div className="flex items-center justify-between border-b border-white/8 px-5 py-4">
        <Logo size={30} />
        <button
          type="button"
          onClick={onClose}
          className="rounded-lg border border-white/10 bg-white/[0.03] px-3 py-1.5 text-[13px] text-silver-300 transition hover:bg-white/[0.08] hover:text-white"
        >
          Close
        </button>
      </div>

      <div className="flex flex-col gap-6 px-5 py-6">
        <div className="grid grid-cols-2 gap-2">
          <button
            type="button"
            onClick={() => {
              onClose();
              openSearch();
            }}
            className="flex h-11 items-center justify-center gap-2 rounded-lg border border-white/10 bg-white/[0.03] text-[13px] font-medium text-silver-100 transition hover:bg-white/[0.08]"
          >
            <Search className="h-4 w-4" aria-hidden="true" />
            Search
          </button>
          <button
            type="button"
            onClick={() => {
              onClose();
              openDrawer();
            }}
            className="flex h-11 items-center justify-center gap-2 rounded-lg border border-white/10 bg-white/[0.03] text-[13px] font-medium text-silver-100 transition hover:bg-white/[0.08]"
          >
            <ShoppingCart className="h-4 w-4" aria-hidden="true" />
            Cart{hydrated && count > 0 ? ` (${count})` : ""}
          </button>
        </div>

        <nav aria-label="Mobile primary">
          <ul className="flex flex-col">
            {navLinks.map((link) => (
              <li key={link.href}>
                <Link
                  href={link.href}
                  onClick={onClose}
                  aria-current={isActive(link.href) ? "page" : undefined}
                  className={cn(
                    "flex items-center justify-between border-b border-white/6 py-3.5 text-[15px] font-medium transition-colors",
                    isActive(link.href)
                      ? "text-white"
                      : "text-silver-200 hover:text-white",
                  )}
                >
                  {link.label}
                  <ChevronRight
                    className="h-4 w-4 text-silver-500"
                    aria-hidden="true"
                  />
                </Link>
              </li>
            ))}
          </ul>
        </nav>

        <div>
          <p className="mb-3 text-[11px] font-medium uppercase tracking-[0.2em] text-silver-500">
            Shop by category
          </p>
          <ul className="grid grid-cols-2 gap-2">
            {categories.map((category) => (
              <li key={category.id}>
                <Link
                  href={`/shop?category=${category.slug}`}
                  onClick={onClose}
                  className="block rounded-lg border border-white/8 bg-white/[0.025] px-3 py-2.5 text-[12.5px] leading-snug text-silver-200 transition hover:border-white/20 hover:bg-white/[0.06] hover:text-white"
                >
                  {category.title}
                </Link>
              </li>
            ))}
          </ul>
        </div>

        <div>
          <p className="mb-3 text-[11px] font-medium uppercase tracking-[0.2em] text-silver-500">
            Help
          </p>
          <ul className="flex flex-col gap-1">
            {[...footerLinks.help, ...footerLinks.legal].map((link) => (
              <li key={link.href}>
                <Link
                  href={link.href}
                  onClick={onClose}
                  className="flex items-center gap-1.5 py-1.5 text-[13.5px] text-silver-300 transition hover:text-white"
                >
                  {link.label}
                </Link>
              </li>
            ))}
          </ul>
        </div>

        <div className="flex flex-col gap-2">
          <ButtonLink href={discordHref} fullWidth onClick={onClose}>
            <MessageSquareText className="h-4 w-4" aria-hidden="true" />
            Open Discord Ticket
            <ArrowUpRight className="h-4 w-4" aria-hidden="true" />
          </ButtonLink>
          <ButtonLink href="/shop" variant="outline" fullWidth onClick={onClose}>
            Browse all packages
          </ButtonLink>
        </div>

        <p className="text-[11px] leading-relaxed text-silver-500">
          {siteConfig.disclaimer}
        </p>
      </div>
    </Dialog>
  );
}
