"use client";

import { usePathname, useRouter } from "next/navigation";
import { useEffect, useMemo, useRef, useState } from "react";
import {
  CornerDownLeft,
  LayoutGrid,
  Package,
  Search,
  Sparkles,
  Star,
  FileText,
} from "lucide-react";
import { Dialog } from "@/components/ui/Dialog";
import { searchStore, type SearchResult, type SearchResultType } from "@/lib/search";
import { useUI } from "@/lib/ui-context";
import { cn } from "@/lib/utils";

const typeIcon: Record<SearchResultType, typeof Package> = {
  product: Package,
  category: LayoutGrid,
  feature: Star,
  service: Sparkles,
  page: FileText,
};

const typeLabel: Record<SearchResultType, string> = {
  product: "Product",
  category: "Category",
  feature: "Included",
  service: "Service",
  page: "Page",
};

export function SearchDialog() {
  const { searchOpen, closeSearch, focusCarouselProduct } = useUI();
  const router = useRouter();
  const pathname = usePathname();
  const [query, setQuery] = useState("");
  const [activeIndex, setActiveIndex] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLUListElement>(null);

  const results = useMemo(() => searchStore(query), [query]);

  useEffect(() => {
    setActiveIndex(0);
  }, [query]);

  useEffect(() => {
    if (!searchOpen) setQuery("");
  }, [searchOpen]);

  useEffect(() => {
    if (!searchOpen) return;
    const timer = window.setTimeout(() => inputRef.current?.focus(), 40);
    return () => window.clearTimeout(timer);
  }, [searchOpen]);

  useEffect(() => {
    const active = listRef.current?.querySelector<HTMLElement>(
      '[data-active="true"]',
    );
    active?.scrollIntoView({ block: "nearest" });
  }, [activeIndex]);

  function select(result: SearchResult) {
    closeSearch();
    // On the home page a product result centres the arc carousel instead of
    // navigating away; anywhere else it opens the product page.
    if (pathname === "/" && result.productSlug) {
      focusCarouselProduct(result.productSlug);
      const target = document.getElementById("featured");
      target?.scrollIntoView({ behavior: "smooth", block: "start" });
      return;
    }
    router.push(result.href);
  }

  function onKeyDown(event: React.KeyboardEvent<HTMLDivElement>) {
    if (results.length === 0) return;
    if (event.key === "ArrowDown") {
      event.preventDefault();
      setActiveIndex((index) => (index + 1) % results.length);
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      setActiveIndex((index) => (index - 1 + results.length) % results.length);
    } else if (event.key === "Enter") {
      event.preventDefault();
      const result = results[activeIndex];
      if (result) select(result);
    }
  }

  return (
    <Dialog
      open={searchOpen}
      onClose={closeSearch}
      title="Search the store"
      variant="command"
      hideHeader
      className="max-h-[72svh]"
    >
      {/* eslint-disable-next-line jsx-a11y/no-static-element-interactions -- key
          routing for the combobox pattern; every result is also a real button */}
      <div onKeyDown={onKeyDown} className="flex h-full flex-col">
        <div className="flex items-center gap-3 border-b border-white/8 px-4 py-3.5">
          <Search className="h-4.5 w-4.5 shrink-0 text-silver-400" aria-hidden="true" />
          <input
            ref={inputRef}
            type="search"
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="Search products, categories, features…"
            aria-label="Search products, categories and services"
            role="combobox"
            aria-expanded="true"
            aria-controls="search-results"
            aria-activedescendant={
              results[activeIndex] ? `search-result-${results[activeIndex].id}` : undefined
            }
            autoComplete="off"
            className="min-w-0 flex-1 bg-transparent text-[15px] text-white outline-none placeholder:text-silver-500"
          />
          <kbd className="hidden rounded border border-white/12 bg-black/40 px-1.5 py-0.5 font-sans text-[10px] text-silver-400 sm:block">
            Esc
          </kbd>
        </div>

        <div className="min-h-0 flex-1 overflow-y-auto overscroll-contain px-2 py-2">
          {results.length === 0 ? (
            <div className="px-4 py-12 text-center">
              <p className="text-[14px] font-medium text-white">
                No matches for “{query}”
              </p>
              <p className="mt-1.5 text-[13px] text-silver-400">
                Try a different term, or browse the full catalogue.
              </p>
              <button
                type="button"
                onClick={() => {
                  closeSearch();
                  router.push("/shop");
                }}
                className="mt-4 rounded-lg border border-white/12 bg-white/[0.04] px-4 py-2 text-[13px] text-silver-100 transition hover:bg-white/[0.09]"
              >
                Open the shop
              </button>
            </div>
          ) : (
            <ul id="search-results" ref={listRef} role="listbox" aria-label="Search results">
              {results.map((result, index) => {
                const Icon = typeIcon[result.type];
                const active = index === activeIndex;
                return (
                  <li key={result.id} role="none">
                    <button
                      type="button"
                      id={`search-result-${result.id}`}
                      role="option"
                      aria-selected={active}
                      data-active={active}
                      onMouseEnter={() => setActiveIndex(index)}
                      onClick={() => select(result)}
                      className={cn(
                        "flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left transition-colors",
                        active ? "bg-white/[0.07]" : "hover:bg-white/[0.04]",
                      )}
                    >
                      <span
                        className={cn(
                          "grid h-9 w-9 shrink-0 place-items-center rounded-lg border",
                          active
                            ? "border-violet-300/35 bg-violet-500/12 text-violet-200"
                            : "border-white/10 bg-white/[0.03] text-silver-400",
                        )}
                      >
                        <Icon className="h-4 w-4" aria-hidden="true" />
                      </span>
                      <span className="min-w-0 flex-1">
                        <span className="block truncate text-[14px] font-medium text-white">
                          {result.title}
                        </span>
                        <span className="block truncate text-[12.5px] text-silver-400">
                          {result.subtitle}
                        </span>
                      </span>
                      <span className="hidden shrink-0 rounded-md border border-white/8 px-1.5 py-0.5 text-[10px] uppercase tracking-wider text-silver-500 sm:block">
                        {typeLabel[result.type]}
                      </span>
                      {active ? (
                        <CornerDownLeft
                          className="hidden h-3.5 w-3.5 shrink-0 text-silver-400 sm:block"
                          aria-hidden="true"
                        />
                      ) : null}
                    </button>
                  </li>
                );
              })}
            </ul>
          )}
        </div>

        <div className="flex items-center justify-between border-t border-white/8 px-4 py-2.5 text-[11px] text-silver-500">
          <span>↑ ↓ to navigate · Enter to open · Esc to close</span>
          <span className="hidden sm:block">
            {results.length} result{results.length === 1 ? "" : "s"}
          </span>
        </div>
      </div>
    </Dialog>
  );
}
