"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useEffect, useState } from "react";
import { Menu, MessageSquareText, Search, ShoppingCart } from "lucide-react";
import { LogoLink } from "@/components/brand/Logo";
import { ButtonLink } from "@/components/ui/Button";
import { MobileMenu } from "@/components/layout/MobileMenu";
import { navLinks } from "@/config/site";
import { useCart } from "@/lib/cart-context";
import { useUI } from "@/lib/ui-context";
import { discordHref } from "@/lib/links";
import { cn } from "@/lib/utils";

export function Navbar() {
  const pathname = usePathname();
  const { count, hydrated, openDrawer } = useCart();
  const { openSearch } = useUI();
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 12);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  // Global Ctrl/Cmd + K.
  useEffect(() => {
    function onKeyDown(event: KeyboardEvent) {
      if (event.key.toLowerCase() === "k" && (event.metaKey || event.ctrlKey)) {
        event.preventDefault();
        openSearch();
      }
    }
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [openSearch]);

  useEffect(() => {
    setMenuOpen(false);
  }, [pathname]);

  const isActive = (href: string) =>
    href === "/" ? pathname === "/" : pathname.startsWith(href);

  return (
    <>
      <a
        href="#main"
        className="sr-only focus:not-sr-only focus:fixed focus:left-4 focus:top-4 focus:z-[200] focus:rounded-lg focus:bg-violet-500 focus:px-4 focus:py-2 focus:text-sm focus:font-medium focus:text-white"
      >
        Skip to content
      </a>

      <header
        className={cn(
          "fixed inset-x-0 top-0 z-100 transition-[background-color,border-color,backdrop-filter] duration-300",
          scrolled
            ? "border-b border-white/8 bg-[rgba(6,6,11,0.82)] backdrop-blur-xl"
            : "border-b border-transparent bg-transparent",
        )}
      >
        <nav
          aria-label="Primary"
          className="shell flex h-[68px] items-center justify-between gap-3"
        >
          <div className="flex items-center gap-1">
            <LogoLink />
          </div>

          <ul className="hidden items-center gap-0.5 lg:flex">
            {navLinks.map((link) => (
              <li key={link.href}>
                <Link
                  href={link.href}
                  aria-current={isActive(link.href) ? "page" : undefined}
                  className={cn(
                    "relative rounded-lg px-3.5 py-2 text-[13.5px] font-medium transition-colors",
                    isActive(link.href)
                      ? "text-white"
                      : "text-silver-300 hover:text-white",
                  )}
                >
                  {link.label}
                  {isActive(link.href) ? (
                    <span
                      aria-hidden="true"
                      className="absolute inset-x-3 -bottom-0.5 h-px bg-gradient-to-r from-transparent via-violet-300 to-transparent"
                    />
                  ) : null}
                </Link>
              </li>
            ))}
          </ul>

          <div className="flex items-center gap-1.5 sm:gap-2">
            <button
              type="button"
              onClick={openSearch}
              aria-label="Search products (Ctrl or Command + K)"
              className="group hidden items-center gap-2 rounded-lg border border-white/10 bg-white/[0.03] py-2 pl-3 pr-2 text-[13px] text-silver-400 transition hover:border-white/20 hover:bg-white/[0.07] hover:text-silver-100 md:flex"
            >
              <Search className="h-4 w-4" aria-hidden="true" />
              <span>Search</span>
              <kbd className="rounded border border-white/12 bg-black/40 px-1.5 py-0.5 font-sans text-[10px] tracking-wide text-silver-400">
                ⌘K
              </kbd>
            </button>

            <button
              type="button"
              onClick={openSearch}
              aria-label="Search products"
              className="grid h-10 w-10 place-items-center rounded-lg border border-white/10 bg-white/[0.03] text-silver-300 transition hover:bg-white/[0.08] hover:text-white md:hidden"
            >
              <Search className="h-[18px] w-[18px]" aria-hidden="true" />
            </button>

            <button
              type="button"
              onClick={openDrawer}
              aria-label={
                hydrated && count > 0
                  ? `Open cart, ${count} item${count === 1 ? "" : "s"} selected`
                  : "Open cart"
              }
              className="relative grid h-10 w-10 place-items-center rounded-lg border border-white/10 bg-white/[0.03] text-silver-200 transition hover:bg-white/[0.08] hover:text-white"
            >
              <ShoppingCart className="h-[18px] w-[18px]" aria-hidden="true" />
              {hydrated && count > 0 ? (
                <span className="absolute -right-1.5 -top-1.5 grid min-w-5 place-items-center rounded-full border border-violet-300/40 bg-violet-500 px-1 text-[11px] font-semibold leading-5 text-white shadow-[0_4px_14px_-4px_rgba(122,98,208,0.9)]">
                  {count > 99 ? "99+" : count}
                </span>
              ) : null}
            </button>

            <ButtonLink
              href={discordHref}
              size="sm"
              className="hidden sm:inline-flex"
            >
              <MessageSquareText className="h-4 w-4" aria-hidden="true" />
              Open Ticket
            </ButtonLink>

            <button
              type="button"
              onClick={() => setMenuOpen(true)}
              aria-label="Open menu"
              aria-expanded={menuOpen}
              className="grid h-10 w-10 place-items-center rounded-lg border border-white/10 bg-white/[0.03] text-silver-200 transition hover:bg-white/[0.08] hover:text-white lg:hidden"
            >
              <Menu className="h-[18px] w-[18px]" aria-hidden="true" />
            </button>
          </div>
        </nav>
      </header>

      <MobileMenu open={menuOpen} onClose={() => setMenuOpen(false)} />
    </>
  );
}
