/** Flat, pre-lowercased index built once at module load. */
export const searchIndex: SearchResult[] = [
  ...products.map<SearchResult>((product) => ({
    id: `product-${product.id}`,
    type: "product",
    title: product.title,
    subtitle: `${getCategoryTitle(product.category)} · ${product.subtitle}`,
    href: `/products/${product.slug}`,
    productSlug: product.slug,
    haystack: [
      product.title,
      product.subtitle,
      product.description,
      getCategoryTitle(product.category),
      ...product.features,
      ...product.keywords,
    ]
      .join(" ")
      .toLowerCase(),
  })),
  ...products.flatMap<SearchResult>((product) =>
    product.features.slice(0, 4).map((feature, index) => ({
      id: `feature-${product.id}-${index}`,
      type: "feature" as const,
      title: feature,
      subtitle: `Included with ${product.title}`,
      href: `/products/${product.slug}`,
      productSlug: product.slug,
      haystack: `${feature} ${product.title}`.toLowerCase(),
    })),
  ),
  ...categories.map<SearchResult>((category) => ({
    id: `category-${category.id}`,
    type: "category",
    title: category.title,
    subtitle: category.description,
    href: `/shop?category=${category.slug}`,
    haystack: `${category.title} ${category.description}`.toLowerCase(),
  })),
  ...customServices.map<SearchResult>((service) => ({
    id: `service-${service.id}`,
    type: "service",
    title: `${service.label} — custom order`,
    subtitle: service.description,
    href: `/custom-order?service=${service.id}`,
    haystack: `${service.label} ${service.description} custom`.toLowerCase(),
  })),
  ...pages.map((page) => ({ ...page, haystack: page.haystack.toLowerCase() })),
];

const TYPE_WEIGHT: Record<SearchResultType, number> = {
  product: 0,
  category: 1,
  service: 2,
  page: 3,
  feature: 4,
};

export function searchStore(query: string, limit = 12): SearchResult[] {
  const trimmed = query.trim().toLowerCase();
  if (!trimmed) {
    return searchIndex.filter((entry) => entry.type === "product").slice(0, limit);
  }
  const terms = trimmed.split(/\s+/).filter(Boolean);

  const scored = searchIndex
    .map((entry) => {
      const title = entry.title.toLowerCase();
      let score = 0;
      for (const term of terms) {
        if (title.startsWith(term)) score += 6;
        else if (title.includes(term)) score += 4;
        else if (entry.haystack.includes(term)) score += 2;
        else return null;
      }
      return { entry, score: score - TYPE_WEIGHT[entry.type] * 0.5 };
    })
    .filter((value): value is { entry: SearchResult; score: number } => value !== null);

  scored.sort((a, b) => b.score - a.score);
  return scored.slice(0, limit).map((value) => value.entry);
}
