"use client";

import { useRouter } from "next/navigation";
import { ArrowRight, ShoppingBag, Sparkles } from "lucide-react";
import { Dialog } from "@/components/ui/Dialog";
import { Button, ButtonLink } from "@/components/ui/Button";
import { CartLineItem } from "@/components/cart/CartLineItem";
import { useCart } from "@/lib/cart-context";
import { formatCurrencyAmount, getCartTotals } from "@/lib/utils";

export function CartDrawer() {
  const router = useRouter();
  const { items, drawerOpen, closeDrawer, clearCart, currency, hydrated } =
    useCart();
  const totals = getCartTotals(items, currency);
  const count = items.reduce((sum, item) => sum + item.quantity, 0);

  const goto = (href: string) => {
    closeDrawer();
    router.push(href);
  };

  return (
    <Dialog
      open={drawerOpen}
      onClose={closeDrawer}
      variant="sheet-right"
      title="Your cart"
      description={
        hydrated && count > 0
          ? `${count} item${count === 1 ? "" : "s"} selected`
          : undefined
      }
      footer={
        items.length > 0 ? (
          <div className="flex flex-col gap-3">
            <div className="flex items-center justify-between text-[13px]">
              <span className="text-silver-400">
                {totals.quoteLines > 0
                  ? `${totals.quoteLines} item${totals.quoteLines === 1 ? "" : "s"} to be quoted`
                  : "All items priced"}
              </span>
              <span className="font-semibold text-white">
                {totals.total > 0
                  ? formatCurrencyAmount(totals.total, currency)
                  : "Quote on request"}
              </span>
            </div>
            <Button fullWidth onClick={() => goto("/checkout")}>
              Checkout
              <ArrowRight className="h-4 w-4" aria-hidden="true" />
            </Button>
            <div className="grid grid-cols-2 gap-2">
              <Button variant="outline" onClick={() => goto("/cart")}>
                View cart
              </Button>
              <Button variant="ghost" onClick={closeDrawer}>
                Continue shopping
              </Button>
            </div>
            <button
              type="button"
              onClick={clearCart}
              className="mx-auto rounded-lg px-3 py-1.5 text-[12.5px] text-silver-500 transition hover:text-red-200"
            >
              Clear cart
            </button>
          </div>
        ) : null
      }
    >
      {items.length === 0 ? (
        <div className="flex h-full flex-col items-center justify-center gap-4 px-6 py-16 text-center">
          <span className="grid h-14 w-14 place-items-center rounded-full border border-white/10 bg-white/[0.03]">
            <ShoppingBag className="h-6 w-6 text-silver-400" aria-hidden="true" />
          </span>
          <div>
            <p className="text-[15px] font-semibold text-white">
              Your cart is empty
            </p>
            <p className="mt-1.5 text-[13px] leading-relaxed text-silver-400">
              Browse the catalogue or build a custom package around your goals.
            </p>
          </div>
          <div className="flex w-full flex-col gap-2">
            <Button fullWidth onClick={() => goto("/shop")}>
              Shop packages
            </Button>
            <ButtonLink
              href="/custom-order"
              variant="outline"
              fullWidth
              onClick={closeDrawer}
            >
              <Sparkles className="h-4 w-4" aria-hidden="true" />
              Build custom order
            </ButtonLink>
          </div>
        </div>
      ) : (
        <ul className="flex flex-col gap-3 px-4 py-4">
          {items.map((item) => (
            <CartLineItem
              key={item.key}
              item={item}
              compact
              onNavigate={closeDrawer}
            />
          ))}
        </ul>
      )}
    </Dialog>
  );
}
